import sys

def iroot(n, k):
    # floor of n^(1/k), exact for integers
    r = int(round(n ** (1.0 / k)))
    if r < 1:
        r = 1
    while r > 1 and r ** k > n:
        r -= 1
    while (r + 1) ** k <= n:
        r += 1
    return r

def mobius(k):
    res = 1
    d = 2
    m = k
    while d * d <= m:
        if m % d == 0:
            m //= d
            if m % d == 0:
                return 0
            res = -res
        d += 1
    if m > 1:
        res = -res
    return res

def main():
    N = int(sys.stdin.readline().strip())
    total = 0
    for k in range(2, 61):
        mu = mobius(k)
        if mu == 0:
            continue
        r = iroot(N, k)
        total += -mu * (r - 1)
    print(total + 1)

